SELECT P.JEITO, COUNT(*) N, COUNT(DISTINCT P.VIDEO_ID) VIDEOS FROM PRATICAS P JOIN VIDEO_TEMAS VT ON VT.VIDEO_ID = P.VIDEO_ID JOIN VIDEOS V ON V.ID = P.VIDEO_ID WHERE VT.TEMA_ID = {{temaId}} AND P.CONSELHO = 0 AND V.STATUS = 'ESTUDADO' AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) GROUP BY P.JEITO ORDER BY N DESC